import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"用户与实名审核","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/user-review.md","filePath":"zh/guide/user-review.md","lastUpdated":1790683574000}'),l={name:"zh/guide/user-review.md"};function i(o,a,p,r,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="用户与实名审核" tabindex="-1">用户与实名审核 <a class="header-anchor" href="#用户与实名审核" aria-label="Permalink to &quot;用户与实名审核&quot;">​</a></h1><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><p>后台「用户管理」可以查看与管理平台的全部注册用户：</p><ul><li>基本资料：账号、UID、注册时间、邀请人</li><li>账户状态：正常 / 异常。异常账户在用户端会有明确提示</li><li>信用分：新用户的初始值在「登录注册配置」里设定</li><li>VIP 等级：由用户的资产或行为达到「VIP 等级设置」中的门槛后确定</li></ul><h2 id="实名认证-kyc" tabindex="-1">实名认证（KYC） <a class="header-anchor" href="#实名认证-kyc" aria-label="Permalink to &quot;实名认证（KYC）&quot;">​</a></h2><p>平台支持<strong>初级认证</strong>与<strong>高级认证</strong>两档，用户在用户端提交资料后由后台审核。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提交资料</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>后台「实名认证」列表出现待审核记录</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>运营查看资料 → 通过 / 驳回</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>用户端状态更新</span></span></code></pre></div><h3 id="认证与提现限额" tabindex="-1">认证与提现限额 <a class="header-anchor" href="#认证与提现限额" aria-label="Permalink to &quot;认证与提现限额&quot;">​</a></h3><p>实名认证等级与<strong>提现限额</strong>挂钩，限额规则在后台的实名限额配置中设定。未达到相应认证等级的用户，提现会受到限制。</p><div class="tip custom-block"><p class="custom-block-title">建议</p><p>驳回时请填写清晰的驳回原因，用户端会看到这条原因。含糊的驳回理由会直接转化为客服工单。</p></div><h2 id="银行卡-收款方式" tabindex="-1">银行卡 / 收款方式 <a class="header-anchor" href="#银行卡-收款方式" aria-label="Permalink to &quot;银行卡 / 收款方式&quot;">​</a></h2><p>用户提交的收款方式同样在后台可见与管理。</p><div class="warning custom-block"><p class="custom-block-title">隐私提醒</p><p>实名资料与收款信息属于用户敏感信息。建议：</p><ul><li>只给必要岗位开放实名审核菜单权限</li><li>不要导出后另存到个人设备</li><li>平台已提供打码（脱敏）配置，可在「基础配置 → 打码配置」中按模块开启</li></ul></div><h2 id="地域限制" tabindex="-1">地域限制 <a class="header-anchor" href="#地域限制" aria-label="Permalink to &quot;地域限制&quot;">​</a></h2><p>平台支持按地区限制访问。开启后，受限地区的用户访问用户端时会看到地域禁止页面。</p><h2 id="用户资产查询" tabindex="-1">用户资产查询 <a class="header-anchor" href="#用户资产查询" aria-label="Permalink to &quot;用户资产查询&quot;">​</a></h2><p>后台可查询任一用户的资产与完整资金流水。每一条流水都记录了变动金额与变动前后的余额，用于核账与客诉排查。</p><div class="danger custom-block"><p class="custom-block-title">后台调账</p><p>后台调账会直接改变用户余额。该操作有完整流水留痕，但<strong>不可自行撤销</strong>——调错了只能再调一笔反向的。执行前务必核对 UID、币种与金额。</p></div>`,18)])])}const b=s(l,[["render",i]]);export{u as __pageData,b as default};
